window.AUTH=window.AUTH||{};window.AUTH["25-1083"]={"d":"25-1083","id":"2025/25-1083","n":"Mullin v. Doe","briefs":[{"k":"petitioner","label":"Brief of petitioners","date":"2026-03-30","url":"https://www.supremecourt.gov/DocketPDF/25/25-1083/403273/20260330193346837_25-1083tsUnitedStates.pdf","side":"pet","n":103},{"k":"respondent","label":"Brief of respondents Dahlia Doe, et al.","date":"2026-04-13","url":"https://www.supremecourt.gov/DocketPDF/25/25-1083/404319/20260413153027211_25-1083%20Brief.pdf","side":"res","n":75},{"k":"respondent","label":"Brief of respondents Fritz Emmanuel Lesly Miot, et al.","date":"2026-04-13","url":"https://www.supremecourt.gov/DocketPDF/25/25-1083/404638/20260416131303542_Miot%2025-1084%20SCOTUS%20merits%20brief%20-%20FINAL.pdf","side":"res","n":94},{"k":"reply","label":"Reply of petitioners","date":"2026-04-20","url":"https://www.supremecourt.gov/DocketPDF/25/25-1083/404848/20260420134959762_25-1083rbUnitedStates.pdf","side":"pet","n":53}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/609us1r60_7mip.pdf","tr":true,"items":[{"t":"case","label":"African Communities Together v. Noem","cite":"2026 WL 395732","y":2026,"court":"D. Mass. Feb. 12","by":{"0":"36","1":"33","2":"16, 39"}},{"t":"case","label":"Amgen Inc. v. Smith","cite":"357 F.3d 103","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/357/103/","by":{"0":"21","2":"28, 29"}},{"t":"case","label":"Aung Doe v. Noem","cite":"2026 WL 184544","y":2026,"court":"N.D. Ill. Jan. 23","by":{"0":"36, 38","1":"10, 43, 52, 49","2":"19, 39"}},{"t":"case","label":"Biden v. Texas","cite":"597 U.S. 785","y":2022,"id":"2021/21-954","sc":1,"sum":"The Government’s rescission of Migrant Protection Protocols did not violate section 1225 of the Immigration and Nationality Act, and the then-Secretary of Homeland Security’s October 29 Memoranda constituted valid final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16","1":"13, 15, 36, 37","2":"30"}},{"t":"case","label":"Board of County Comm’rs v. United States Dep’t of Transp.","cite":"955 F.3d 96","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/955/96/","by":{"0":"41"}},{"t":"case","label":"Bouarfa v. Mayorkas","cite":"604 U.S. 6","y":2024,"id":"2024/23-583","sc":1,"sum":"The Court held that revocation of an approved visa petition under 8 U.S.C. §1155 based on a sham-marriage determination by the Secretary of Homeland Security is the kind of discretionary decision that falls within the purview of §1252(a)(2)(B)(ii), which strips federal courts of jurisdiction to review certain actions “in the discretion of” the agency.","sumSrc":"Oyez","by":{"0":"23, 35, 44","1":"29","2":"30","3":"20"}},{"t":"case","label":"Citizens to Preserve Overton Park, Inc. v. Volpe","cite":"401 U.S. 402","y":1971,"id":"1970/1066","sc":1,"sum":"Under § 4 (f) of the Department. of Transportation Act of 1966 and § 138 of the Federal-Aid Highway Act of 1968, the Secretary of Transportation may not authorize use of federal funds to finance construction of highways through public parks if a \"feasible and prudent\" alternative route exists. If no such route is available, he may approve construction only if there has been \"all possible planning to minimize harm\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","1":"49","3":"20"}},{"t":"case","label":"City of Rialto v. West Coast Loading Corp.","cite":"581 F.3d 865","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/581/865/","sum":"Recognizing “distinction between precluded judicial review...and [permissible] judicial review of ‘methods’ and other collateral issues”.","sumSrc":"brief:1","by":{"0":"27","1":"33"}},{"t":"case","label":"DCH Reg’l Med. Ctr. v. Azar","cite":"925 F.3d 503","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/925/503/","by":{"0":"21","1":"33","2":"20, 28","3":"5"}},{"t":"case","label":"DHS v. Regents of the Univ. of Cal.","cite":"591 U.S. 1","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/1/","sc":1,"op":1,"ar":8,"sum":"Finding the President’s statements insufficiently probative where “[t]he relevant actors were most directly” the Acting Secretary and the Attorney General.","sumSrc":"brief:0","by":{"0":"50, 51","1":"36","2":"30, 35, 42","3":"21-23"}},{"t":"case","label":"Delgado v. Quarantillo","cite":"643 F.3d 52","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/643/52/","by":{"0":"29"}},{"t":"case","label":"Department of Commerce v. New York","cite":"588 U.S. 752","y":2019,"id":"2018/18-966","sc":1,"op":2,"ar":4,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"44","2":"22, 39","3":"20"}},{"t":"case","label":"EPA v. Calumet Shreveport Ref., L.L.C.","cite":"605 U.S. 627","y":2025,"url":"https://supreme.justia.com/cases/federal/us/605/627/","sc":1,"op":1,"ar":2,"by":{"0":"19, 20, 34","1":"18, 24, 25, 33","3":"3, 13"}},{"t":"case","label":"FCC v. Prometheus Radio Project","cite":"592 U.S. 414","y":2021,"id":"2020/19-1231","sc":1,"sum":"The Federal Communications Commission’s 2017 decision to repeal or modify three of its media ownership rules was not arbitrary or capricious for purposes of the Administrative Procedure Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40"}},{"t":"case","label":"FDA v. Wages & White Lion Invs., L.L.C.","cite":"604 U.S. 542","y":2025,"id":"2024/23-1038","sc":1,"sum":"The Fifth Circuit erred in setting aside as arbitrary and capricious the FDA’s orders denying respondents’ applications for authorization to market new e-cigarette products pursuant to The Family Smoking Prevention and Tobacco Control Act of 2009; the Fifth Circuit also relied on an incorrect standard to reject the FDA’s claim of harmless error regarding the agency’s failure to consider marketing plans submitted by respondents.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35, 40","3":"16, 18"}},{"t":"case","label":"Fiallo v. Bell","cite":"430 U.S. 787","y":1977,"id":"1976/75-6297","sc":1,"sum":"Sections 101 (b) (1) (D) and 101 (b) (2) of the Immigration and Nationality Act of 1952, which have the effect of excluding the relationship between an illegitimate child and his natural father (as opposed to his natural mother) from the special preference immigration status accorded by the Act to the \"child\" or \"parent\" of a United States citizen or lawful permanent resident, held not to be unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49","2":"43"}},{"t":"case","label":"Florida Health Scis. Ctr., Inc. v. Secretary of Health & Hum. Servs.","cite":"830 F.3d 515","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/830/515/","by":{"0":"27, 28","1":"33"}},{"t":"case","label":"Garland v. Ming Dai","cite":"593 U.S. 357","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/357/","sc":1,"by":{"0":"35, 38","1":"44"}},{"t":"case","label":"Haitian Evangelical Clergy Ass’n v. Trump","cite":"789 F. Supp. 3d 255","y":2025,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/789/255/","by":{"0":"12","2":"8, 16, 35"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"op":1,"sum":"Explaining that even permanent residence is not a “right” but “a matter of permission and tolerance”.","sumSrc":"opinion","by":{"0":"47, 49","2":"43, 44, 45","3":"8"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"22","1":"37, 38"}},{"t":"case","label":"Hotel & Rest. Emps. Union v. Smith","cite":"846 F.2d 1499","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/846/1499/","by":{"0":"2, 22, 23","1":"4, 5, 37","2":"29"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"ar":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"48","2":"43"}},{"t":"case","label":"Lincoln v. Vigil","cite":"508 U.S. 182","y":1993,"id":"1992/91-1833","sc":1,"sum":"The Indian Health Service receives yearly lump-sum appropriations from Congress, and expends the funds under authority of the Snyder Act and the Indian Health Care Improvement Act to provide health care for American Indian and Alaska Native people. Out of these appropriations the Service funded, from 1978 to 1985, the Indian Children's Program (Program), which provided clinical services to handicapped Indian …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Mathews v. Diaz","cite":"426 U.S. 67","y":1976,"id":"1974/73-1046","sc":1,"ar":1,"sum":"Title 42 U. S. C. § 1395o (2) qualifies for enrollment in the Medicare supplemental medical insurance program residents of the United States who are 65 or older, but in subsection (B) denies eligibility to aliens unless they have been admitted for permanent residence and also have resided in the United States for at least five years. Appellee Diaz filed a class action suit in the District Court attacking the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 49","2":"43, 44, 45"}},{"t":"case","label":"McNary v. Haitian Refugee Ctr., Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"op":1,"ar":10,"sum":"Construing the word “determination” in another judicial-review bar as “describ[ing] a single act,” rather than the “procedure employed in making decisions”.","sumSrc":"opinion","by":{"0":"31-33","1":"12, 15, 28-34, 36","2":"12, 14, 16, 17, 18, 19, 25, 26, 27, 28","3":"5-7, 10, 12"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n v. State Farm Mut. Auto Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"25, 44","2":"34, 37, 38"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"sum":"Held that the habeas corpus statute extends to American citizens held overseas by American forces operating subject to an American chain of command even if part of a larger multinational force.","sumSrc":"Oyez","by":{"0":"41","3":"16"}},{"t":"case","label":"NTPSA v. Noem","cite":"2025 WL 4058572","y":2025,"by":{"0":"36","1":"43, 52, 55","2":"42"}},{"t":"case","label":"NTPSA v. Noem","cite":"2026 WL 687355","y":2026,"court":"9th Cir. Mar. 11","by":{"0":"24, 32, 35, 36"}},{"t":"case","label":"National Archives & Records Admin. v. Favish","cite":"541 U.S. 157","y":2004,"id":"2003/02-954","sc":1,"sum":"The Court held that the Foster family's interest in privacy outweighed the public interest in seeing pictures from Vincent Foster's death scene. The public interest could only trump privacy interests if Favish could present evidence that the government might have acted improperly. Favish failed to do so.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Nouritajer v. Jaddou","cite":"18 F.4th 85","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/18/85/","by":{"0":"27, 28"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"op":2,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 35","1":"25, 26","2":"25, 31","3":"4, 9, 14"}},{"t":"case","label":"Philip Morris Prods. S.A. v. International Trade Comm’n","cite":"63 F.4th 1328","y":2023,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/63/1328/","by":{"0":"37","1":"44"}},{"t":"case","label":"Rajah v. Mukasey","cite":"544 F.3d 427","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/544/427/","by":{"0":"49","2":"43, 44, 45"}},{"t":"case","label":"Ramos v. Nielsen","cite":"336 F. Supp. 3d 1075","y":2018,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/336/1075/","by":{"0":"11","2":"6, 42"}},{"t":"case","label":"Ramos v. Nielsen","cite":"709 F. Supp. 3d 871","y":2023,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/709/871/","by":{"0":"11"}},{"t":"case","label":"Ramos v. Wolf","cite":"975 F.3d 872","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/872/","by":{"0":"11, 23, 30, 43, 50, 51","2":"6, 16, 42","3":"7"}},{"t":"case","label":"Skagit County Pub. Hosp. Dist. No. 2 v. Shalala","cite":"80 F.3d 379","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/80/379/","by":{"0":"22, 28","1":"33","2":"28","3":"5"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"op":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"0":"15, 18, 42, 45, 46-50","2":"13, 42, 43, 44, 46, 47","3":"3, 21-23"}},{"t":"case","label":"United States v. Chemical Found., Inc.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"sum":"1. A decree of the Circuit Court of Appeals, entered prior to the taking effect of the Jurisdictional Act of February 13, 1925, and affirming dismissal on the merits of a bill by the United States to set aside, as unauthorized and fraudulently procured, sales of patent and other rights and properties seized pursuant to the Trading, with the Enemy Act, was reviewable by this Court on appeal (Jud. Code §§ 128, 241). …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"United States v. Miller","cite":"604 U.S. 518","y":2025,"id":"2024/23-824","sc":1,"sum":"Section 106(a) of the Bankruptcy Code abrogates the Government’s sovereign immunity with respect to a §544(b) claim but that waiver does not extend to state-law claims nested within that federal claim.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21","1":"27"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"United States v. Tohono O’odham Nation","cite":"563 U.S. 307","y":2011,"id":"2010/09-846","sc":1,"sum":"The Court held that the Court of Federal Claims lacked jurisdiction to hear a suit against the federal government about a claim already being litigated against the government in another court, even when the lawsuits seek different relief based on the same set of facts.","sumSrc":"Oyez","by":{"0":"20","1":"26"}},{"t":"case","label":"United States Army Corps of Eng’rs v. Hawkes Co., Inc.","cite":"578 U.S. 590","y":2016,"id":"2015/15-290","sc":1,"sum":"The Court determined that the Army Corps of Engineers’ jurisdictional determination that a property constituted “water of the United States” was a final agency action subject to judicial review under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. Natural Res. Def. Council, Inc.","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","3":"15"}},{"t":"case","label":"Village of Arlington Heights v. Metropolitan Housing Development Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"op":7,"ar":9,"sum":"After finding that MHDC had proper federal standing, since it acted on behalf of black plaintiffs who stood to suffer direct and measurable injuries from Arlington's denial, the Court held that it failed to establish Arlington's racially discriminatory intent or purpose.","sumSrc":"Oyez","by":{"0":"18, 49","2":"13, 41, 42, 45, 46"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"op":3,"ar":3,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 42","2":"15"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"0":"4"}},{"t":"usc","label":"5 U.S.C. § 559","url":"https://www.law.cornell.edu/uscode/text/5/559","stext":{"head":"§559. Effect on other laws; effect of subsequent statute","paras":[[0,"This subchapter, chapter 7, and sections 1305, 3105, 3344, 4301(2)(E), 5372, and 7521 of this title, and the provisions of section 5335(a)(B) of this title that relate to administrative law judges, do not limit or repeal additional requirements imposed by statute or otherwise recognized by law. Except as otherwise required by law, requirements or privileges relating to evidence or procedure apply equally to agencies and persons. Each agency is granted the authority necessary to comply with the requirements of this subchapter through the issuance of rules or otherwise. Subsequent statute may not be held to supersede or modify this subchapter, chapter 7, sections 1305, 3105, 3344, 4301(2)(E), 5372, or 7521 of this title, or the provisions of section 5335(a)(B) of this title that relate to administrative law judges, except to the extent that it does so expressly."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/559?type=usc&year=mostrecent&link-type=html"},"head":"§559. Effect on other laws; effect of subsequent statute","tname":"Government Organization and Employees","by":{"0":"29","2":"15"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)","(a)(1)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"30, 29","1":"32"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"0":"29"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"0":"21"}},{"t":"usc","label":"5 U.S.C. § 705","url":"https://www.law.cornell.edu/uscode/text/5/705","stext":{"head":"§705. Relief pending review","paras":[[0,"When an agency finds that justice so requires, it may postpone the effective date of action taken by it, pending judicial review. On such conditions as may be required and to the extent necessary to prevent irreparable injury, the reviewing court, including the court to which a case may be taken on appeal from or on application for certiorari or other writ to a reviewing court, may issue all necessary and appropriate process to postpone the effective date of an agency action or to preserve status or rights pending conclusion of the review proceedings."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/705?type=usc&year=mostrecent&link-type=html"},"ar":2,"head":"§705. Relief pending review","tname":"Government Organization and Employees","by":{"0":"10, 13","1":"11"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/4978","by":{"0":"5","1":"5"}},{"t":"usc","label":"6 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/6/552","subs":["(d)"],"by":{"0":"6"}},{"t":"usc","label":"6 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/6/557","by":{"0":"6"}},{"t":"usc","label":"8 U.S.C. § 1157","url":"https://www.law.cornell.edu/uscode/text/8/1157","subs":["(e)"],"by":{"0":"38"}},{"t":"usc","label":"8 U.S.C. § 1160","url":"https://www.law.cornell.edu/uscode/text/8/1160","subs":["(e)","(e)(3)(B)","(e)(1)"],"stext":{"head":"§1160. Special agricultural workers","paras":[[0,"(a) Lawful residence"],[0,"(1) In general"],[1,"The Attorney General shall adjust the status of an alien to that of an alien lawfully admitted for temporary residence if the Attorney General determines that the alien meets the following requirements:"],[0,"(A) Application period"],[2,"The alien must apply for such adjustment during the 18-month period beginning on the first day of the seventh month that begins after November 6, 1986."],[0,"(B) Performance of seasonal agricultural services and residence in the United States"],[2,"The alien must establish that he has—"],[3,"(i) resided in the United States, and"],[3,"(ii) performed seasonal agricultural services in the United States for at least 90 man-days,"],[2,"during the 12-month period ending on May 1, 1986. For purposes of the previous sentence, performance of seasonal agricultural services in the United States for more than one employer on any one day shall be counted as performance of services for only 1 man-day."],[0,"(C) Admissible as immigrant"],[2,"The alien must establish that he is admissible to the United States as an immigrant, except as otherwise provided under subsection (c)(2)."],[0,"(2) Adjustment to permanent residence"],[1,"The Attorney General shall adjust the status of any alien provided lawful temporary resident status under paragraph (1) to that of an alien lawfully admitted for permanent residence on the following date:"],[0,"(A) Group 1"],[2,"Subject to the numerical limitation established under subparagraph (C), in the case of an alien who has established, at the time of application for temporary residence under paragraph (1), that the alien performed seasonal agricultural services in the United States for at least 90 man-days during each of the 12-month periods ending on May 1, 1984, 1985, and 1986, the adjustment shall occur on the first day after the end of the one-year period that begins on the later of (I) the date the alien was granted such temporary resident status, or (II) the day after the last day of the application period described in paragraph (1)(A)."],[0,"(B) Group 2"],[2,"In the case of aliens to which subparagraph (A) does not apply, the adjustment shall occur on the day after the last day of the two-year period that begins on the later of (I) the date the alien was granted such temporary resident status, or (II) the day after the last day of the application period described in paragraph (1)(A)."],[0,"(C) Numerical limitation"],[2,"Subparagraph (A) shall not apply to more than 350,000 aliens. If more than 350,000 aliens meet the requirements of such subparagraph, such subparagraph shall apply to the 350,000 aliens whose applications for adjustment were first filed under paragraph (1) and subparagraph (B) shall apply to the remaining aliens."],[0,"(3) Termination of temporary residence"],[1,"(A) During the period of temporary resident status granted an alien under paragraph (1), the Attorney General may terminate such status only upon a determination under this chapter that the alien is deportable."],[1,"(B) Before any alien becomes eligible for adjustment of status under paragraph (2), the Attorney General may deny adjustment to permanent status and provide for termination of the temporary resident status granted such alien under paragraph (1) if—"],[2,"(i) the Attorney General finds by a preponderance of the evidence that the adjustment to temporary resident status was the result of fraud or willful misrepresentation as set out in section 1182(a)(6)(C)(i) of this title, or"],[2,"(ii) the alien commits an act that (I) makes the alien inadmissible to the United States as an immigrant, except as provided under subsection (c)(2), or (II) is convicted of a felony or 3 or more misdemeanors committed in the United States."],[0,"(4) Authorized travel and employment during temporary residence"],[1,"During the period an alien is in lawful temporary resident status granted under this subsection, the alien has the right to travel abroad (including commutation from a residence abroad) and shall be granted authorization to engage in employment in the United States and shall be provided an \"employment authorized\" endorsement or other appropriate work permit, in the same manner as for aliens lawfully admitted for permanent residence."],[0,"(5) In general"],[1,"Except as otherwise provided in this subsection, an alien who acquires the status of an alien lawfully admitted for temporary residence under paragraph (1), such status not having changed, is considered to be an alien lawfully admitted for permanent residence (as described in section 1101(a)(20) of this title), other than under any provision of the immigration laws."],[0,"(b) Applications for adjustment of status"],[0,"(1) To whom may be made"],[0,"(A) Within the United States"],[2,"The Attorney General shall provide that applications for adjustment of status under subsection (a) may be filed—"],[3,"(i) with the Attorney General, or"],[3,"(ii) with a designated entity (designated under paragraph (2)), but only if the applicant consents to the forwarding of the application to the Attorney General."],[0,"(B) Outside the United States"],[2,"The Attorney General, in cooperation with the Secretary of State, shall provide a procedure whereby an alien may apply for adjustment of status under subsection (a)(1) at an appropriate consular office outside the United States. If the alien otherwise qualifies for such adjustment, the Attorney General shall provide such documentation of authorization to enter the United States and to have the alien's status adjusted upon entry as may be necessary to carry out the provisions of this section."],[0,"(2) Designation of entities to receive applications"],[1,"For purposes of receiving applications under this section, the Attorney General—"],[2,"(A) shall designate qualified voluntary organizations and other qualified State, local, community, farm labor organizations, and associations of agricultural employers, and"],[2,"(B) may designate such other persons as the Attorney General determines are qualified and have substantial experience, demonstrated competence, and traditional long-term involvement in the preparation and submittal of applications for adjustment of status under section 1159 or 1255 of this title, Public Law 89–732 [8 U.S.C. 1255 note], or Public Law 95–145 [8 U.S.C. 1255 note]."],[0,"(3) Proof of eligibility"],[0,"(A) In general"],[2,"An alien may establish that he meets the requirement of subsection (a)(1)(B)(ii) through government employment records, records supplied by employers or collective bargaining organizations, and such other reliable documentation as the alien may provide. The Attorney General shall establish special procedures to credit properly work in cases in which an alien was employed under an assumed name."],[0,"(B) Documentation of work history"],[2,"(i) An alien applying for adjustment of status under subsection (a)(1) has the burden of proving by a preponderance of the evidence that the alien has worked the requisite number of man-days (as required under subsection (a)(1)(B)(ii))."],[2,"(ii) If an employer or farm labor contractor employing such an alien has kept proper and adequate records respecting such employment, the alien's burden of proof under clause (i) may be met by securing timely production of those records under regulations to be promulgated by the Attorney General."],[2,"(iii) An alien can meet such burden of proof if the alien establishes that the alien has in fact performed the work described in subsection (a)(1)(B)(ii) by producing sufficient evidence to show the extent of that employment as a matter of just and reasonable inference. In such a case, the burden then shifts to the Attorney General to disprove the alien's evidence with a showing which negates the reasonableness of the inference to be drawn from the evidence."],[0,"(4) Treatment of applications by designated entities"],[1,"Each designated entity must agree to forward to the Attorney General applications filed with it in accordance with paragraph (1)(A)(ii) but not to forward to the Attorney General applications filed with it unless the applicant has consented to such forwarding. No such entity may make a determination required by this section to be made by the Attorney General."],[0,"(5) Limitation on access to information"],[1,"Files and records prepared for purposes of this section by designated entities operating under this section are confidential and the Attorney General and the Service shall not have access to such files or records relating to an alien without the consent of the alien, except as allowed by a court order issued pursuant to paragraph (6) of this subsection."],[0,"(6) Confidentiality of information"],[0,"(A) In general"],[2,"Except as provided in this paragraph, neither the Attorney General, nor any other official or employee of the Department of Justice, or bureau or agency thereof, may—"],[3,"(i) use the information furnished by the applicant pursuant to an application filed under this section for any purpose other than to make a determination on the application, including a determination under subsection (a)(3)(B), or for enforcement of paragraph (7);"],[3,"(ii) make any publication whereby the information furnished by any particular individual can be identified; or"],[3,"(iii) permit anyone other than the sworn officers and employees of the Department or bureau or agency or, with respect to applications filed with a designated entity, that designated entity, to examine individual applications."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1160?type=usc&year=mostrecent&link-type=html"},"head":"§1160. Special agricultural workers","tname":"Aliens and Nationality","by":{"0":"31, 31, 32","1":"28","3":"6, 6"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(2)(A)(i)","(a)(2)(A)(iv)","(a)(2)(B)(ii)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"15","1":"29","3":"8, 8, 8"}},{"t":"usc","label":"8 U.S.C. § 1254a","url":"https://www.law.cornell.edu/uscode/text/8/1254a","subs":["(a)","(b)","(b)(1)(A)","(b)(1)","(b)(1)(B)","(b)(1)(C)","(b)(2)","(b)(3)","(b)(3)(A)","(b)(3)(B)","(b)(3)(C)","(b)(5)(A)","(c)","(a)(4)(B)","(c)(2)(A)","(e)","(i)(1)(C)"],"stext":{"head":"§1254a. Temporary protected status","paras":[[0,"(a) Granting of status"],[0,"(1) In general"],[1,"In the case of an alien who is a national of a foreign state designated under subsection (b) (or in the case of an alien having no nationality, is a person who last habitually resided in such designated state) and who meets the requirements of subsection (c), the Attorney General, in accordance with this section—"],[2,"(A) may grant the alien temporary protected status in the United States and shall not remove the alien from the United States during the period in which such status is in effect, and"],[2,"(B) shall authorize the alien to engage in employment in the United States and provide the alien with an \"employment authorized\" endorsement or other appropriate work permit."],[0,"(2) Duration of work authorization"],[1,"Work authorization provided under this section shall be effective throughout the period the alien is in temporary protected status under this section."],[0,"(3) Notice"],[1,"(A) Upon the granting of temporary protected status under this section, the Attorney General shall provide the alien with information concerning such status under this section."],[1,"(B) If, at the time of initiation of a removal proceeding against an alien, the foreign state (of which the alien is a national) is designated under subsection (b), the Attorney General shall promptly notify the alien of the temporary protected status that may be available under this section."],[1,"(C) If, at the time of designation of a foreign state under subsection (b), an alien (who is a national of such state) is in a removal proceeding under this subchapter, the Attorney General shall promptly notify the alien of the temporary protected status that may be available under this section."],[1,"(D) Notices under this paragraph shall be provided in a form and language that the alien can understand."],[0,"(4) Temporary treatment for eligible aliens"],[1,"(A) In the case of an alien who can establish a prima facie case of eligibility for benefits under paragraph (1), but for the fact that the period of registration under subsection (c)(1)(A)(iv) has not begun, until the alien has had a reasonable opportunity to register during the first 30 days of such period, the Attorney General shall provide for the benefits of paragraph (1)."],[1,"(B) In the case of an alien who establishes a prima facie case of eligibility for benefits under paragraph (1), until a final determination with respect to the alien's eligibility for such benefits under paragraph (1) has been made, the alien shall be provided such benefits."],[0,"(5) Clarification"],[1,"Nothing in this section shall be construed as authorizing the Attorney General to deny temporary protected status to an alien based on the alien's immigration status or to require any alien, as a condition of being granted such status, either to relinquish nonimmigrant or other status the alien may have or to execute any waiver of other rights under this chapter. The granting of temporary protected status under this section shall not be considered to be inconsistent with the granting of nonimmigrant status under this chapter."],[0,"(b) Designations"],[0,"(1) In general"],[1,"The Attorney General, after consultation with appropriate agencies of the Government, may designate any foreign state (or any part of such foreign state) under this subsection only if—"],[2,"(A) the Attorney General finds that there is an ongoing armed conflict within the state and, due to such conflict, requiring the return of aliens who are nationals of that state to that state (or to the part of the state) would pose a serious threat to their personal safety;"],[2,"(B) the Attorney General finds that—"],[3,"(i) there has been an earthquake, flood, drought, epidemic, or other environmental disaster in the state resulting in a substantial, but temporary, disruption of living conditions in the area affected,"],[3,"(ii) the foreign state is unable, temporarily, to handle adequately the return to the state of aliens who are nationals of the state, and"],[3,"(iii) the foreign state officially has requested designation under this subparagraph; or"],[2,"(C) the Attorney General finds that there exist extraordinary and temporary conditions in the foreign state that prevent aliens who are nationals of the state from returning to the state in safety, unless the Attorney General finds that permitting the aliens to remain temporarily in the United States is contrary to the national interest of the United States."],[1,"A designation of a foreign state (or part of such foreign state) under this paragraph shall not become effective unless notice of the designation (including a statement of the findings under this paragraph and the effective date of the designation) is published in the Federal Register. In such notice, the Attorney General shall also state an estimate of the number of nationals of the foreign state designated who are (or within the effective period of the designation are likely to become) eligible for temporary protected status under this section and their immigration status in the United States."],[0,"(2) Effective period of designation for foreign states"],[1,"The designation of a foreign state (or part of such foreign state) under paragraph (1) shall—"],[2,"(A) take effect upon the date of publication of the designation under such paragraph, or such later date as the Attorney General may specify in the notice published under such paragraph, and"],[2,"(B) shall remain in effect until the effective date of the termination of the designation under paragraph (3)(B)."],[1,"For purposes of this section, the initial period of designation of a foreign state (or part thereof) under paragraph (1) is the period, specified by the Attorney General, of not less than 6 months and not more than 18 months."],[0,"(3) Periodic review, terminations, and extensions of designations"],[0,"(A) Periodic review"],[2,"At least 60 days before end of the initial period of designation, and any extended period of designation, of a foreign state (or part thereof) under this section the Attorney General, after consultation with appropriate agencies of the Government, shall review the conditions in the foreign state (or part of such foreign state) for which a designation is in effect under this subsection and shall determine whether the conditions for such designation under this subsection continue to be met. The Attorney General shall provide on a timely basis for the publication of notice of each such determination (including the basis for the determination, and, in the case of an affirmative determination, the period of extension of designation under subparagraph (C)) in the Federal Register."],[0,"(B) Termination of designation"],[2,"If the Attorney General determines under subparagraph (A) that a foreign state (or part of such foreign state) no longer continues to meet the conditions for designation under paragraph (1), the Attorney General shall terminate the designation by publishing notice in the Federal Register of the determination under this subparagraph (including the basis for the determination). Such termination is effective in accordance with subsection (d)(3), but shall not be effective earlier than 60 days after the date the notice is published or, if later, the expiration of the most recent previous extension under subparagraph (C)."],[0,"(C) Extension of designation"],[2,"If the Attorney General does not determine under subparagraph (A) that a foreign state (or part of such foreign state) no longer meets the conditions for designation under paragraph (1), the period of designation of the foreign state is extended for an additional period of 6 months (or, in the discretion of the Attorney General, a period of 12 or 18 months)."],[0,"(4) Information concerning protected status at time of designations"],[1,"At the time of a designation of a foreign state under this subsection, the Attorney General shall make available information respecting the temporary protected status made available to aliens who are nationals of such designated foreign state."],[0,"(5) Review"],[0,"(A) Designations"],[2,"There is no judicial review of any determination of the Attorney General with respect to the designation, or termination or extension of a designation, of a foreign state under this subsection."],[0,"(B) Application to individuals"],[2,"The Attorney General shall establish an administrative procedure for the review of the denial of benefits to aliens under this subsection. Such procedure shall not prevent an alien from asserting protection under this section in removal proceedings if the alien demonstrates that the alien is a national of a state designated under paragraph (1)."],[0,"(c) Aliens eligible for temporary protected status"],[0,"(1) In general"],[0,"(A) Nationals of designated foreign states"],[2,"Subject to paragraph (3), an alien, who is a national of a state designated under subsection (b)(1) (or in the case of an alien having no nationality, is a person who last habitually resided in such designated state), meets the requirements of this paragraph only if—"],[3,"(i) the alien has been continuously physically present in the United States since the effective date of the most recent designation of that state;"],[3,"(ii) the alien has continuously resided in the United States since such date as the Attorney General may designate;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1254a?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1254a. Temporary protected status","tname":"Aliens and Nationality","by":{"0":"15, 6, 17, 24, 39, 40, 6, 17, 24, 39, 40, 6, 17, 24, 39, 40, 6, 17, 24, 39, 40, 6, 17, 24, 39, 40, 6, 17, 24, 39, 40, 6, 17, 24, 39, 40, 6, 17, 24, 39, 40, 6, 17, 24, 39, 40, 6, 17, 24, 39, 40, 38, 38, 38","1":"i, 2, 5-8, 12, 14-22, 24-26, 30, 32, 34, 35, 37, 39, 40, 42, 45-48, 51","3":"13, 14, 22, 13, 13, 19, 17, 15-17, 9, 10, 1, 3-12, 14, 13, 13, 9"}},{"t":"usc","label":"16 U.S.C. § 1536","url":"https://www.law.cornell.edu/uscode/text/16/1536","subs":["(b)(3)(A)"],"by":{"0":"38"}},{"t":"usc","label":"33 U.S.C. § 2321a","url":"https://www.law.cornell.edu/uscode/text/33/2321a","subs":["(b)"],"by":{"0":"38"}},{"t":"usc","label":"42 U.S.C. § 1395ww","url":"https://www.law.cornell.edu/uscode/text/42/1395ww","subs":["(d)(10)(C)(iii)(II)","(r)(3)(A)"],"by":{"0":"22, 21"}},{"t":"reg","label":"Designation of Haiti for Temporary Protected Status:, 75 Fed. Reg. 3476","url":"https://www.govinfo.gov/link/fr/75/3476","by":{"0":"11","2":"6"}},{"t":"reg","label":"86 Fed. Reg. 41,863","url":"https://www.govinfo.gov/link/fr/86/41863","by":{"0":"12","2":"6, 7"}},{"t":"reg","label":"Designation of Syrian Arab Republic for Temporary Protected Status, 77 Fed. Reg. 19,026","url":"https://www.govinfo.gov/link/fr/77/19026","by":{"0":"8, 40","1":"8"}},{"t":"reg","label":"Exec. Order No. 14,159, 90 Fed. Reg. 8443","url":"https://www.govinfo.gov/link/fr/90/8443","by":{"0":"44, 51","1":"50, 51","2":"8, 9","3":"20"}},{"t":"reg","label":"Extension of the Designation of Syria for Temporary Protected Status, 83 Fed. Reg. 9329","url":"https://www.govinfo.gov/link/fr/83/9329","by":{"0":"7"}},{"t":"reg","label":"Extension of the Designation of Yemen for Temporary Protected Status, 83 Fed. Reg. 40,307","url":"https://www.govinfo.gov/link/fr/83/40307","by":{"0":"7"}},{"t":"reg","label":"Extension of the Designation of Somalia for Temporary Protected Status, 83 Fed. Reg. 43,695","url":"https://www.govinfo.gov/link/fr/83/43695","by":{"0":"7"}},{"t":"reg","label":"Extension of South Sudan Designation for Temporary Protected Status:, 90 Fed. Reg. 19,217","url":"https://www.govinfo.gov/link/fr/90/19217","by":{"0":"45","1":"40","3":"16"}},{"t":"reg","label":"82 Fed. Reg. 44,205","url":"https://www.govinfo.gov/link/fr/82/44205","by":{"0":"7"}},{"t":"reg","label":"Partial Vacatur of 2024 Temporary Protected Status Decision for Haiti, 90 Fed. Reg. 10,511","url":"https://www.govinfo.gov/link/fr/90/10511","by":{"0":"12","2":"8, 10"}},{"t":"reg","label":"Six-Month Extension of Temporary Protected Status Benefits for Orderly Transition Before Termination of Guinea’s Designation for Temporary P, 81 Fed. Reg. 66,064","url":"https://www.govinfo.gov/link/fr/81/66064","by":{"0":"7"}},{"t":"reg","label":"Termination of Designation of Lebanon Under Temporary Protected Status Program, 58 Fed. Reg. 7582","url":"https://www.govinfo.gov/link/fr/58/7582","by":{"0":"7"}},{"t":"reg","label":"Termination of Designation of Rwanda Under Temporary Protected Status After Final 6-Month Extension, 62 Fed. Reg. 33,442","url":"https://www.govinfo.gov/link/fr/62/33442","by":{"0":"7"}},{"t":"reg","label":"Termination of the Designation of Haiti for Temporary Protected Status:, 83 Fed. Reg. 2648","url":"https://www.govinfo.gov/link/fr/83/2648","by":{"0":"11","2":"6"}},{"t":"reg","label":"90 Fed. Reg. 28,760","url":"https://www.govinfo.gov/link/fr/90/28760","by":{"0":"12","2":"8, 10"}},{"t":"reg","label":"90 Fed. Reg. 54,733","url":"https://www.govinfo.gov/link/fr/90/54733","by":{"0":"4, 11-13, 37, 41, 47, 48","2":"3, 8, 9, 10, 36, 37, 38, 40","3":"18, 19"}},{"t":"reg","label":"Termination of the Designation of Montserrat Under the Temporary Protected Status Program, 69 Fed. Reg. 40,642","url":"https://www.govinfo.gov/link/fr/69/40642","by":{"0":"7"}},{"t":"reg","label":"Termination of the Designation of South Sudan for Temporary Protected Status, 90 Fed. Reg. 50,484","url":"https://www.govinfo.gov/link/fr/90/50484","by":{"0":"45","1":"43","2":"10, 33"}},{"t":"reg","label":"Termination of the Designation of Syria for Temporary Protected Status, 90 Fed. Reg. 45,398","url":"https://www.govinfo.gov/link/fr/90/45398","by":{"0":"4, 8, 9, 38, 42, 45","1":"10, 11, 42, 45, 47, 48, 51, 54","2":"10","3":"19"}},{"t":"case","label":"Axon Enter. v. FTC","cite":"598 U.S. 175","y":2023,"id":"2022/21-86","sc":1,"sum":"The statutory review schemes set out in the Securities Exchange Act and Federal Trade Commission Act do not displace a district court’s federal-question jurisdiction over claims challenging as unconstitutional the structure or existence of the SEC or FTC.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18, 21, 34"}},{"t":"case","label":"Bowen v. Mich. Acad. of Fam. Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":2,"ar":7,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 27, 28, 30, 31, 34, 36","2":"14, 15, 26","3":"5, 6"}},{"t":"case","label":"Cal. Wilderness Coal. v. U.S. Dep't of Energy","cite":"631 F.3d 1072","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/631/1072/","by":{"1":"40","2":"32"}},{"t":"case","label":"CASA, Inc. v. Noem","cite":"792 F. Supp. 3d 576","y":2025,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/792/576/","by":{"1":"43"}},{"t":"case","label":"City & Cnty. of San Francisco v. Env’t Prot. Agency","cite":"604 U.S. 334","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/334/","sc":1,"by":{"1":"25","2":"25","3":"4, 5"}},{"t":"case","label":"Commissioner v. Zuch","cite":"605 U.S. 422","y":2025,"id":"2024/24-416","sc":1,"ar":1,"sum":"The United States Tax Court lacks jurisdiction under 26 U. S. C. §6330 to resolve disputes between a taxpayer and the Internal Revenue Service when the IRS is no longer pursuing a levy.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"579 U.S. 261","y":2016,"id":"2015/15-446","sc":1,"op":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Dep’t of Com. v. New York","cite":"588 U.S. 752","y":2019,"url":"https://supreme.justia.com/cases/federal/us/588/752/","sc":1,"op":2,"by":{"1":"i, 17, 49, 51"}},{"t":"case","label":"FDA v. White Lion","cite":"604 U.S. 542","y":2025,"url":"https://supreme.justia.com/cases/federal/us/604/542/","sc":1,"by":{"1":"48"}},{"t":"case","label":"Garcia v. USCIS","cite":"146 F.4th 743","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/146/743/","by":{"1":"30"}},{"t":"case","label":"Gebhardt v. Nielsen","cite":"879 F.3d 980","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/879/980/","sum":"Construing 2006 statute giving Secretary “sole and unreviewable discretion” in immigration cases involving sex offenders to bar all but “predicate legal questions” and constitutional claims.","sumSrc":"brief:1","by":{"1":"30","3":"8"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"589 U.S. 221","y":2020,"id":"2019/18-776","sc":1,"op":2,"ar":2,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"1":"29, 35, 36","2":"14, 15, 31"}},{"t":"case","label":"Gutierrez v. Ada","cite":"528 U.S. 250","y":2000,"id":"1999/99-51","sc":1,"sum":"The Court held that \"[t]he Guam Organic Act does not require a runoff election when a candidate slate has received a majority of the votes cast for Governor and Lieutenant Governor of the Territory, but not a majority of the number of ballots cast in the simultaneous general election.\" Justice Souter wrote for the Court that an \"obvious reading\" of the law requires only a majority of votes cast in that one specific race, \"Congress did not shift its attention when it used 'any election' unadorned by a gubernatorial reference or other definite modifier.\".","sumSrc":"Oyez","by":{"1":"23, 26"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"op":1,"ar":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"27, 35"}},{"t":"case","label":"Judulang v. Holder","cite":"565 U.S. 42","y":2011,"id":"2011/10-694","sc":1,"sum":"The Court held that the policy used to determine whether a resident alien is able to ask for relief from deportation under a repealed portion of immigration laws is “arbitrary and capricious” under the Administrative Procedure Act, 5 U.S.C. § 706(2)(A).","sumSrc":"Oyez","by":{"1":"36","2":"30"}},{"t":"case","label":"Mahmoud v. Taylor","cite":"606 U.S. 522","y":2025,"id":"2024/24-297","sc":1,"sum":"Parents challenging the Montgomery County Board of Education’s introduction of certain “LGBTQ+-inclusive” storybooks, along with the Board’s decision to withhold parental opt outs from that instruction, are entitled to a preliminary injunction.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"McLaughlin Chiropractic Assoc. Inc., v. McKesson Corp.","cite":"606 U.S. 146","y":2025,"id":"2024/23-1226","sc":1,"sum":"The Hobbs Act does not bind district courts in civil enforcement proceedings to an agency’s interpretation of a statute. District courts must independently determine the law’s meaning under ordinary principles of statutory interpretation while affording appropriate respect to the agency’s interpretation.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23","2":"14"}},{"t":"case","label":"Miot v. Trump","cite":"2026 WL 266413","y":2026,"court":"D.D.C. Feb. 2","op":8,"ar":3,"by":{"1":"43"}},{"t":"case","label":"Nat’l TPS All. v. Noem","cite":"150 F.4th 1000","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/150/1000/","by":{"1":"5, 37, 48","2":"29, 30"}},{"t":"case","label":"Nat'l TPS All. v. Noem","cite":"163 F.4th 1152","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/163/1152/","by":{"1":"52"}},{"t":"case","label":"Nat'l TPS All. v. Noem","cite":"166 F.4th 739","y":2026,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/166/739/","sum":"Describing and rejecting Petitioners’ argument.","sumSrc":"brief:1","by":{"1":"9, 34, 35, 37","2":"16"}},{"t":"case","label":"Nat'l TPS All. v. Noem","cite":"169 F.4th 796","y":2026,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/169/796/","by":{"1":"20","3":"5, 7, 10, 14"}},{"t":"case","label":"Nat'l TPS All. v. Noem","cite":"773 F. Supp. 3d 807","y":2025,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/773/807/","by":{"1":"7","2":"18, 35"}},{"t":"case","label":"Nat'l TPS All. v. Noem","cite":"798 F. Supp. 3d 1108","y":2025,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/798/1108/","by":{"1":"20, 35, 43, 51","2":"16"}},{"t":"case","label":"Nixon v. Mo. Mun. League","cite":"541 U.S. 125","y":2004,"id":"2003/02-1238","sc":1,"sum":"The Court held that the act allows states to prevent municipalities from providing telecommunications services. The act only allows federal preemption of state and local efforts to prevent \"any private entity\" from providing telecommunications services.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Noem v. Nat'l TPS All.","cite":"145 S. Ct. 2728","y":2025,"url":"https://www.courtlistener.com/c/S.%20Ct./145/2728/","sc":1,"by":{"1":"35"}},{"t":"case","label":"Reno v. Cath. Soc. Servs.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"ar":2,"sum":"The record is insufficient to allow this Court to decide all issues necessary to determine whether the District Courts had jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 28, 30-34","3":"5, 7"}},{"t":"case","label":"Saget v. Trump","cite":"375 F. Supp. 3d 280","y":2019,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/375/280/","by":{"1":"55","2":"6, 16, 18, 32, 34, 38, 39, 41, 42, 46"}},{"t":"case","label":"Sanchez v. Mayorkas","cite":"593 U.S. 409","y":2021,"id":"2020/20-315","sc":1,"sum":"An individual who entered the United States unlawfully is not eligible to become a lawful permanent resident under 8 U.S.C. §1255 even if the United States has granted the individual temporary protected status.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"5"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"UAW v. Brock","cite":"477 U.S. 274","y":1986,"id":"1985/84-1777","sc":1,"sum":"To supplement state unemployment insurance benefits, the Trade Act of 1974 (Act) provides federally funded trade readjustment allowance (TRA) benefits to workers laid off because of competition from imports. As authorized by the Act, the Secretary of Labor (Secretary) has contracted out to state unemployment insurance agencies the job of making individual eligibility determinations for the benefits. To qualify for …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"United States v. Alvarez-Sanchez","cite":"511 U.S. 350","y":1994,"id":"1993/92-1812","sc":1,"sum":"The Court held that the provisions of the federal statute in question do not apply to suspects being held solely on state charges. The Court explained that no delay is said to occur until the suspect is arrested and detained for a federal crime. The six-hour period only begins to expire from the point of a suspect's federal arrest and charging.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Urias-Orellana v. Bondi","cite":"146 S. Ct. 845","y":2026,"id":"2025/24-777","sc":1,"sum":"The Court held that a federal court of appeals must defer to the Board of Immigration Appeals’ judgment that a given set of undisputed facts does not demonstrate mistreatment severe enough to constitute “persecution” under 8 U.S.C. § 1101(a)(42).","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"West Virginia v. Env’t Prot. Agency","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"by":{"1":"15, 35"}},{"t":"case","label":"Wilkinson v. Garland","cite":"601 U.S. 209","y":2024,"id":"2023/22-666","sc":1,"ar":2,"sum":"The Immigration Judge’s discretionary decision that Mr. Wilkinson failed to satisfy 8 U. S. C. §1229b(b)(1)(D)’s “exceptional and extremely unusual” hardship standard for determining eligibility for cancellation of removal is a mixed question of law and fact, reviewable under §1252(a)(2)(D)’s jurisdiction restoring exception for “questions of law”; the Third Circuit’s holding that the IJ’s decision was unreviewable under §1252(a)(2)(B)(i) was in error.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26, 32"}},{"t":"reg","label":"65 Fed. Reg. 30438","url":"https://www.govinfo.gov/link/fr/65/30438","by":{"1":"40"}},{"t":"reg","label":"78 Fed. Reg. 36223","url":"https://www.govinfo.gov/link/fr/78/36223","by":{"1":"8"}},{"t":"reg","label":"89 Fed. Reg. 5562","url":"https://www.govinfo.gov/link/fr/89/5562","by":{"1":"8"}},{"t":"reg","label":"90 Fed. Reg. 53378","url":"https://www.govinfo.gov/link/fr/90/53378","by":{"1":"44","2":"10"}},{"t":"reg","label":"90 Fed. Reg. 9040","url":"https://www.govinfo.gov/link/fr/90/9040","by":{"1":"44","2":"10"}},{"t":"reg","label":"91 Fed. Reg. 10402","url":"https://www.govinfo.gov/link/fr/91/10402","by":{"1":"10","2":"10"}},{"t":"case","label":"ABM Onsite Servs.-W., Inc. v. NLRB","cite":"849 F.3d 1137","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/849/1137/","by":{"2":"34, 36"}},{"t":"case","label":"Aman v. Cort Furniture Rental Corp.","cite":"85 F.3d 1074","y":1996,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/85/1074/","by":{"2":"48"}},{"t":"case","label":"CASA de Md., Inc. v. Trump","cite":"355 F. Supp. 3d 307","y":2018,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/355/307/","by":{"2":"16, 17"}},{"t":"case","label":"CASA, Inc. v. Noem","cite":"2025 WL 3514378","y":2025,"court":"D. Md.","by":{"2":"42"}},{"t":"case","label":"Centro Presente v. DHS","cite":"332 F. Supp. 3d 393","y":2018,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/332/393/","by":{"2":"16, 42"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Coalition on Sensible Transp. Inc. v. Dole","cite":"642 F. Supp. 573","y":1986,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./642/573/","by":{"2":"32, 33"}},{"t":"case","label":"Dastmalchi v. INS","cite":"660 F.2d 880","y":1981,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/660/880/","by":{"2":"27"}},{"t":"case","label":"Elhady v. Kable","cite":"993 F.3d 208","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/993/208/","by":{"2":"46"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"579 U.S. 211","y":2016,"id":"2015/15-415","sc":1,"sum":"The Court held that, because the Department of Labor did not give adequate reasons for altering its position on whether service advisors are exempt from overtime compensation under the Fair Labor Standards Act (FLSA), the case should be remanded for reinterpretation that does not give controlling weight to the Department’s 2011 position.","sumSrc":"Oyez","by":{"2":"34, 36"}},{"t":"case","label":"Friends of Animals v. U.S. Bureau of Land Mgmt.","cite":"728 F. Supp. 3d 45","y":2024,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/728/45/","by":{"2":"32"}},{"t":"case","label":"vi Gozlon-Peretz v. United States","cite":"498 U.S. 395","y":1991,"id":"1990/89-7370","sc":1,"sum":"Supervised release applies for all drug offenses in the categories specified by ADAA § 1002 that were committed after the ADAA was enacted but before November 1, 1987.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"Hunt v. Cromartie","cite":"526 U.S. 541","y":1999,"id":"1998/98-85","sc":1,"sum":"The Court held that despite strong evidence of racial gerrymandering, the North Carolina General Assembly's motivations were in dispute. As such, further inquiry was warranted on this alone. Moreover, since accusations of racial gerrymandering rise to the level of being constitutionally significant, they must be evaluated with strict scrutiny.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Korematsu v. United States","cite":"323 U.S. 214","y":1944,"id":"1940-1955/323us214","sc":1,"sum":"The Court held that compulsory exclusion of citizens during times of war is justified in order to reduce the risk of espionage.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"2":"14, 15"}},{"t":"case","label":"Medical Marijuana, Inc. v. Horn","cite":"604 U.S. 593","y":2025,"id":"2024/23-365","sc":1,"sum":"The Court held that under the civil provision of RICO, a plaintiff may seek treble damages for business or property loss even if the loss resulted from a personal injury.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Mhany Mgmt., Inc. v. County of Nassau","cite":"819 F.3d 581","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/819/581/","by":{"2":"48"}},{"t":"case","label":"NAACP v. DHS","cite":"364 F. Supp. 3d 568","y":2019,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/364/568/","by":{"2":"42"}},{"t":"case","label":"National TPS All. v. Noem","cite":"2026 BL 42675","y":2026,"court":"9th Cir. Feb. 9","url":"https://www.courtlistener.com/c/BL/2026/42675/","by":{"2":"16"}},{"t":"case","label":"Ramos v. Wolf","cite":"59 F.4th 1010","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/59/1010/","by":{"2":"6, 16"}},{"t":"case","label":"U.S. Dep’t of Agric. v. Moreno","cite":"413 U.S. 528","y":1973,"id":"1972/72-534","sc":1,"sum":"The Court upheld the District Court and maintained that amended Section 3 violated the Fifth Amendment in creating two types of households – one in which all members were related and one in which at least one member was unrelated. Justice William J. Brennan, Jr., writing for the majority, acknowledged the interest of Congress in preventing abuse of the Food Stamp program.","sumSrc":"Oyez","by":{"2":"13, 36, 46"}},{"t":"case","label":"United States v. Suquilanda","cite":"116 F.4th 129","y":2024,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/116/129/","by":{"2":"44"}},{"t":"case","label":"Washington v. Davis","cite":"426 U.S. 229","y":1976,"id":"1975/74-1492","sc":1,"sum":"In a 7-to-2 decision, the Court held that the procedures and written personnel test did not constitute racial discrimination under the Equal Protection Clause. The Court found that the Clause was designed to prevent official discrimination on the basis of race; laws or other official acts that had racially disproportionate impacts did not automatically become constitutional violations.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Wojciechowicz v. Garland","cite":"77 F.4th 511","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/77/511/","by":{"2":"27"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"2":"42, 45"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"11, 16","3":"21"}},{"t":"usc","label":"8 U.S.C. § 1155","url":"https://www.law.cornell.edu/uscode/text/8/1155","stext":{"head":"§1155. Revocation of approval of petitions; effective date","paras":[[0,"The Secretary of Homeland Security may, at any time, for what he deems to be good and sufficient cause, revoke the approval of any petition approved by him under section 1154 of this title. Such revocation shall be effective as of the date of approval of any such petition."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1155?type=usc&year=mostrecent&link-type=html"},"head":"§1155. Revocation of approval of petitions; effective date","tname":"Aliens and Nationality","by":{"2":"30","3":"8"}},{"t":"law","label":"Omnibus Consolidated Appropriations Act, Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"2":"26"}},{"t":"reg","label":"76 Fed. Reg. 29000","url":"https://www.govinfo.gov/link/fr/76/29000","by":{"2":"6"}},{"t":"reg","label":"77 Fed. Reg. 59943","url":"https://www.govinfo.gov/link/fr/77/59943","by":{"2":"6"}},{"t":"reg","label":"79 Fed. Reg. 11808","url":"https://www.govinfo.gov/link/fr/79/11808","by":{"2":"6"}},{"t":"reg","label":"80 Fed. Reg. 51582","url":"https://www.govinfo.gov/link/fr/80/51582","by":{"2":"6"}},{"t":"reg","label":"88 Fed. Reg. 5022","url":"https://www.govinfo.gov/link/fr/88/5022","by":{"2":"6, 7"}},{"t":"reg","label":"89 Fed. Reg. 54484","url":"https://www.govinfo.gov/link/fr/89/54484","by":{"2":"6, 7"}},{"t":"reg","label":"90 Fed. Reg. 8805","url":"https://www.govinfo.gov/link/fr/90/8805","by":{"2":"10"}},{"t":"reg","label":"90 Fed. Reg. 20309","url":"https://www.govinfo.gov/link/fr/90/20309","by":{"2":"10"}},{"t":"reg","label":"90 Fed. Reg. 23697","url":"https://www.govinfo.gov/link/fr/90/23697","by":{"2":"10"}},{"t":"reg","label":"90 Fed. Reg. 24151","url":"https://www.govinfo.gov/link/fr/90/24151","by":{"2":"10"}},{"t":"reg","label":"90 Fed. Reg. 30086","url":"https://www.govinfo.gov/link/fr/90/30086","by":{"2":"10"}},{"t":"reg","label":"90 Fed. Reg. 30089","url":"https://www.govinfo.gov/link/fr/90/30089","by":{"2":"10"}},{"t":"reg","label":"90 Fed. Reg. 43225","url":"https://www.govinfo.gov/link/fr/90/43225","by":{"2":"10"}},{"t":"reg","label":"90 Fed. Reg. 54735","url":"https://www.govinfo.gov/link/fr/90/54735","by":{"2":"3, 9, 10, 37"}},{"t":"reg","label":"90 Fed. Reg. 58028","url":"https://www.govinfo.gov/link/fr/90/58028","by":{"2":"10"}},{"t":"reg","label":"91 Fed. Reg. 1547","url":"https://www.govinfo.gov/link/fr/91/1547","by":{"2":"10"}},{"t":"case","label":"African Communities Together v. Noem","cite":"2026 WL 948591","y":2026,"court":"D. Mass. Apr. 8","by":{"3":"2"}},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Kemp v. United States","cite":"596 U.S. 528","y":2022,"id":"2021/21-5726","sc":1,"op":2,"sum":"The term “mistake” in Federal Rule of Civil Procedure 60(b)(1) includes a judge’s errors of law; because Kemp’s motion alleged such an error, it was cognizable under Rule 60(b)(1) and untimely under Rule 60(c)’s 1-year limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"7"}},{"t":"case","label":"Trump v. CASA, Inc.","cite":"606 U.S. 831","y":2025,"id":"2024/24a884","sc":1,"sum":"Because universal injunctions likely exceed the equitable authority that Congress has granted to federal courts, the Court grants the Government’s applications for a partial stay of the injunctions entered below regarding the implementation and enforcement of President Trump’s Executive Order No. 14160, but only to the extent that the injunctions are broader than necessary to provide complete relief to each plaintiff with standing to sue.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"11"}},{"t":"case","label":"Winter v. Natural Res. Def. Council, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"sum":"The Court held that the standard for properly granting a preliminary injunction is not based on the \"possibility\" of irreparable harm to marine life, but rather that \"irreparable injury is likely\" in the absence of such an injunction.","sumSrc":"Oyez","by":{"3":"24"}},{"t":"case","label":"Wisconsin v. City of New York","cite":"517 U.S. 1","y":1996,"id":"1995/94-1614","sc":1,"sum":"The Court held that the decision not to use the PES-based statistical correction would not be reviewed under a strict scrutiny standard of \"one person - one vote\" because there was no showing of intentional discrimination by the Secretary of Commerce.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"law","label":"Pub. L. No. 89-236","url":"https://www.govinfo.gov/link/statute/79/916","by":{"3":"8"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)(2)(D)"],"by":{"3":"13"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","by":{"3":"22"}},{"t":"reg","label":"Extension of the Designation of Somalia Under Temporary Protected Status Program, 57 Fed. Reg. 32,232","url":"https://www.govinfo.gov/link/fr/57/32232","by":{"3":"17"}}]};